    discount_minor bigint DEFAULT 0 NOT NULL,
    tax_rate_bp integer DEFAULT 0 NOT NULL,
    tax_minor bigint DEFAULT 0 NOT NULL,
    total_minor bigint DEFAULT 0 NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT invoice_lines_discount_within_subtotal CHECK ((discount_minor <= subtotal_minor)),
    CONSTRAINT invoice_lines_quantity_positive CHECK ((quantity > 0)),
    CONSTRAINT invoice_lines_tax_rate_range CHECK (((tax_rate_bp >= 0) AND (tax_rate_bp <= 10000))),
    CONSTRAINT invoice_lines_totals_add_up CHECK ((total_minor = ((subtotal_minor - discount_minor) + tax_minor)))
);

