    currency character varying(3) NOT NULL,
    subtotal_minor bigint DEFAULT 0 NOT NULL,
    discount_minor bigint DEFAULT 0 NOT NULL,
    tax_minor bigint DEFAULT 0 NOT NULL,
    total_minor bigint DEFAULT 0 NOT NULL,
    tax_rate_bp integer DEFAULT 0 NOT NULL,
    tax_label character varying(32) DEFAULT ''::character varying NOT NULL,
    tax_inclusive boolean DEFAULT false NOT NULL,
    seller_name character varying(255) DEFAULT ''::character varying NOT NULL,
    seller_address text,
    seller_tax_id character varying(64),
    buyer_name character varying(255) DEFAULT ''::character varying NOT NULL,
    buyer_address text,
    buyer_tax_id character varying(64),
    plan_id bigint,
    promotion_id bigint,
    period_start date,
    period_end date,
    issued_at timestamp without time zone,
    due_at timestamp without time zone,
    paid_at timestamp without time zone,
    voided_at timestamp without time zone,
    void_reason text,
    notes text,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT invoices_amounts_non_negative CHECK (((subtotal_minor >= 0) AND (discount_minor >= 0) AND (tax_minor >= 0))),
    CONSTRAINT invoices_discount_within_subtotal CHECK ((discount_minor <= subtotal_minor)),
    CONSTRAINT invoices_number_matches_status CHECK (((((status)::text = 'draft'::text) AND (number IS NULL)) OR (((status)::text <> 'draft'::text) AND (number IS NOT NULL)))),
    CONSTRAINT invoices_status CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'open'::character varying, 'paid'::character varying, 'void'::character varying, 'uncollectible'::character varying])::text[]))),
    CONSTRAINT invoices_tax_rate_range CHECK (((tax_rate_bp >= 0) AND (tax_rate_bp <= 10000))),
    CONSTRAINT invoices_totals_add_up CHECK ((total_minor = ((subtotal_minor - discount_minor) + tax_minor)))
);

